def queue_using_stacks(operations: list[tuple]) -> list:
    in_stack, out_stack, output = [], [], []
    def transfer():
        if not out_stack:
            while in_stack: out_stack.append(in_stack.pop())
    for op in operations:
        cmd = op[0]
        if cmd == 'push': in_stack.append(op[1])
        elif cmd == 'pop':
            transfer()
            output.append(out_stack.pop() if out_stack else None)
        elif cmd == 'peek':
            transfer()
            output.append(out_stack[-1] if out_stack else None)
        elif cmd == 'empty':
            output.append(len(in_stack) == 0 and len(out_stack) == 0)
    return output

